/**
 * Invitation token helpers for the POS acceptance flow.
 *
 * The backend stores only a SHA-256 digest of the raw invitation token. The POS
 * receives the raw token in the email redirect and must hash it before calling
 * `accept_staff_invitation`. The raw token is never sent to the RPC.
 */

export const INVITATION_TOKEN_PATTERN = /^[A-Za-z0-9_-]{43}$/;

const toHex = (bytes: Uint8Array): string =>
  Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");

/** Validate the 43-character base64url token generated by the Edge Function. */
export function isInvitationToken(value: unknown): value is string {
  return typeof value === "string" && INVITATION_TOKEN_PATTERN.test(value);
}

/** Hash a raw invitation token and return a lowercase SHA-256 hex digest. */
export async function sha256Hex(value: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value));
  return toHex(new Uint8Array(digest));
}
